insert into public.content_chunks (topic_id, title, body, source_name, source_url, license)
select 'atoms-nuclear', 'Atom', 'Atoms are the basic particles of the chemical elements and the fundamental building blocks of matter. An atom consists of a nucleus of protons and generally neutrons, surrounded by an electromagnetically bound swarm of electrons. The chemical elements are distinguished from each other by the number of protons that are in their atoms. For example, any atom that contains 11 protons is sodium, and any atom that contains 29 protons is copper. Atoms with the same number of protons but a different number of neutrons are called isotopes of the same element. Atoms are extremely small, typically around 100 picometers across. A human hair is about a million carbon atoms wide. Atoms are smaller than the shortest wavelength of visible light, which means humans cannot see atoms with conventional microscopes. They are so small that accurately predicting their behavior using classical physics is not possible due to quantum effects.', 'Wikipedia: Atom', 'https://en.wikipedia.org/w/index.php?title=Atom&oldid=1377869405', 'CC BY-SA 4.0. Wikipedia contributors (see page history). Excerpted and split into passages.'
where not exists (select 1 from public.content_chunks where topic_id = 'atoms-nuclear' and body = 'Atoms are the basic particles of the chemical elements and the fundamental building blocks of matter. An atom consists of a nucleus of protons and generally neutrons, surrounded by an electromagnetically bound swarm of electrons. The chemical elements are distinguished from each other by the number of protons that are in their atoms. For example, any atom that contains 11 protons is sodium, and any atom that contains 29 protons is copper. Atoms with the same number of protons but a different number of neutrons are called isotopes of the same element. Atoms are extremely small, typically around 100 picometers across. A human hair is about a million carbon atoms wide. Atoms are smaller than the shortest wavelength of visible light, which means humans cannot see atoms with conventional microscopes. They are so small that accurately predicting their behavior using classical physics is not possible due to quantum effects.');
insert into public.content_chunks (topic_id, title, body, source_name, source_url, license)
select 'atoms-nuclear', 'Atom', 'More than 99.94% of an atom''s mass is in the nucleus. Protons have a positive electric charge and neutrons have no charge, so the nucleus is positively charged. The electrons are negatively charged, and this opposing charge is what binds them to the nucleus. If the numbers of protons and electrons are equal, as they normally are, then the atom is electrically neutral as a whole. A charged atom is called an ion. If an atom has more electrons than protons, then it has an overall negative charge and is called a negative ion (or anion). Conversely, if it has more protons than electrons, it has a positive charge and is called a positive ion (or cation). The electrons of an atom are attracted to the protons in an atomic nucleus by the electromagnetic force. The protons and neutrons in the nucleus are attracted to each other by the nuclear force. This force is usually stronger than the electromagnetic force that repels the positively charged protons from one another. Under certain circumstances, the repelling electromagnetic force becomes stronger than the nuclear force. In this case, the nucleus splits and leaves behind different elements. This is a form of nuclear decay.', 'Wikipedia: Atom', 'https://en.wikipedia.org/w/index.php?title=Atom&oldid=1377869405', 'CC BY-SA 4.0. Wikipedia contributors (see page history). Excerpted and split into passages.'
where not exists (select 1 from public.content_chunks where topic_id = 'atoms-nuclear' and body = 'More than 99.94% of an atom''s mass is in the nucleus. Protons have a positive electric charge and neutrons have no charge, so the nucleus is positively charged. The electrons are negatively charged, and this opposing charge is what binds them to the nucleus. If the numbers of protons and electrons are equal, as they normally are, then the atom is electrically neutral as a whole. A charged atom is called an ion. If an atom has more electrons than protons, then it has an overall negative charge and is called a negative ion (or anion). Conversely, if it has more protons than electrons, it has a positive charge and is called a positive ion (or cation). The electrons of an atom are attracted to the protons in an atomic nucleus by the electromagnetic force. The protons and neutrons in the nucleus are attracted to each other by the nuclear force. This force is usually stronger than the electromagnetic force that repels the positively charged protons from one another. Under certain circumstances, the repelling electromagnetic force becomes stronger than the nuclear force. In this case, the nucleus splits and leaves behind different elements. This is a form of nuclear decay.');
insert into public.content_chunks (topic_id, title, body, source_name, source_url, license)
select 'atoms-nuclear', 'Atom', 'Atoms can attach to one or more other atoms by chemical bonds to form chemical compounds such as molecules or crystals. The ability of atoms to attach and detach from each other is responsible for most of the physical changes observed in nature. Chemistry is the science that studies these changes.', 'Wikipedia: Atom', 'https://en.wikipedia.org/w/index.php?title=Atom&oldid=1377869405', 'CC BY-SA 4.0. Wikipedia contributors (see page history). Excerpted and split into passages.'
where not exists (select 1 from public.content_chunks where topic_id = 'atoms-nuclear' and body = 'Atoms can attach to one or more other atoms by chemical bonds to form chemical compounds such as molecules or crystals. The ability of atoms to attach and detach from each other is responsible for most of the physical changes observed in nature. Chemistry is the science that studies these changes.');
insert into public.content_chunks (topic_id, title, body, source_name, source_url, license)
select 'atoms-nuclear', 'Atom: History of atomic theory', 'The word atom is derived from the ancient Greek word Atomos, which means "uncuttable". However, this ancient idea was based in philosophical reasoning rather than scientific reasoning. Modern atomic theory is not based on these old concepts. In the early 19th century, the scientist John Dalton found evidence that matter really is composed of discrete units, and so applied the word atom to those units.', 'Wikipedia: Atom', 'https://en.wikipedia.org/w/index.php?title=Atom&oldid=1377869405', 'CC BY-SA 4.0. Wikipedia contributors (see page history). Excerpted and split into passages.'
where not exists (select 1 from public.content_chunks where topic_id = 'atoms-nuclear' and body = 'The word atom is derived from the ancient Greek word Atomos, which means "uncuttable". However, this ancient idea was based in philosophical reasoning rather than scientific reasoning. Modern atomic theory is not based on these old concepts. In the early 19th century, the scientist John Dalton found evidence that matter really is composed of discrete units, and so applied the word atom to those units.');
insert into public.content_chunks (topic_id, title, body, source_name, source_url, license)
select 'atoms-nuclear', 'Atom: Philosophy', 'The basic idea that matter is made up of tiny indivisible particles is an idea that appeared in many ancient cultures. These ancient ideas were based on philosophical reasoning rather than scientific evidence, and modern atomic theory is not based on these old concepts. That said, the word atom is derived from the term atomos ("uncuttable") used by the Greek philosophers Leucippus and his pupil Democritus, who developed this idea in the 5th century BC.', 'Wikipedia: Atom', 'https://en.wikipedia.org/w/index.php?title=Atom&oldid=1377869405', 'CC BY-SA 4.0. Wikipedia contributors (see page history). Excerpted and split into passages.'
where not exists (select 1 from public.content_chunks where topic_id = 'atoms-nuclear' and body = 'The basic idea that matter is made up of tiny indivisible particles is an idea that appeared in many ancient cultures. These ancient ideas were based on philosophical reasoning rather than scientific evidence, and modern atomic theory is not based on these old concepts. That said, the word atom is derived from the term atomos ("uncuttable") used by the Greek philosophers Leucippus and his pupil Democritus, who developed this idea in the 5th century BC.');
insert into public.content_chunks (topic_id, title, body, source_name, source_url, license)
select 'atoms-nuclear', 'Atom: Dalton''s law of multiple proportions', 'In the early 1800s, John Dalton compiled experimental data gathered by him and other scientists and discovered a pattern now known as the "law of multiple proportions". He noticed that in any group of chemical compounds which all contain two particular chemical elements, the amount of Element A per measure of Element B will differ across these compounds by ratios of small whole numbers. This pattern suggested that each element combines with other elements in multiples of a basic unit of weight, with each element having a unit of unique weight. Dalton decided to call these units "atoms". For example, there are two types of tin oxide: one is a grey powder that is 88.1% tin and 11.9% oxygen, and the other is a white powder that is 78.7% tin and 21.3% oxygen. Adjusting these figures, in the grey powder there is about 13.5 g of oxygen for every 100 g of tin, and in the white powder there is about 27 g of oxygen for every 100 g of tin. 13.5 and 27 form a ratio of 1:2. Dalton concluded that in the grey oxide there is one atom of oxygen for every atom of tin, and in the white oxide there are two atoms of oxygen for every atom of tin (SnO and SnO2).', 'Wikipedia: Atom', 'https://en.wikipedia.org/w/index.php?title=Atom&oldid=1377869405', 'CC BY-SA 4.0. Wikipedia contributors (see page history). Excerpted and split into passages.'
where not exists (select 1 from public.content_chunks where topic_id = 'atoms-nuclear' and body = 'In the early 1800s, John Dalton compiled experimental data gathered by him and other scientists and discovered a pattern now known as the "law of multiple proportions". He noticed that in any group of chemical compounds which all contain two particular chemical elements, the amount of Element A per measure of Element B will differ across these compounds by ratios of small whole numbers. This pattern suggested that each element combines with other elements in multiples of a basic unit of weight, with each element having a unit of unique weight. Dalton decided to call these units "atoms". For example, there are two types of tin oxide: one is a grey powder that is 88.1% tin and 11.9% oxygen, and the other is a white powder that is 78.7% tin and 21.3% oxygen. Adjusting these figures, in the grey powder there is about 13.5 g of oxygen for every 100 g of tin, and in the white powder there is about 27 g of oxygen for every 100 g of tin. 13.5 and 27 form a ratio of 1:2. Dalton concluded that in the grey oxide there is one atom of oxygen for every atom of tin, and in the white oxide there are two atoms of oxygen for every atom of tin (SnO and SnO2).');
insert into public.content_chunks (topic_id, title, body, source_name, source_url, license)
select 'atoms-nuclear', 'Atom: Dalton''s law of multiple proportions', 'Dalton also analyzed iron oxides. There is one type of iron oxide that is a black powder which is 78.1% iron and 21.9% oxygen; and there is another iron oxide that is a red powder which is 70.4% iron and 29.6% oxygen. Adjusting these figures, in the black powder there is about 28 g of oxygen for every 100 g of iron, and in the red powder there is about 42 g of oxygen for every 100 g of iron. 28 and 42 form a ratio of 2:3. Dalton concluded that in these oxides, for every two atoms of iron, there are two or three atoms of oxygen respectively. These substances are known today as iron(II) oxide and iron(III) oxide, and their formulas are FeO and Fe2O3 respectively. Iron(II) oxide''s formula is normally written as FeO, but since it is a crystalline substance we could alternately write it as Fe2O2, and when we contrast that with Fe2O3, the 2:3 ratio for the oxygen is plain to see.', 'Wikipedia: Atom', 'https://en.wikipedia.org/w/index.php?title=Atom&oldid=1377869405', 'CC BY-SA 4.0. Wikipedia contributors (see page history). Excerpted and split into passages.'
where not exists (select 1 from public.content_chunks where topic_id = 'atoms-nuclear' and body = 'Dalton also analyzed iron oxides. There is one type of iron oxide that is a black powder which is 78.1% iron and 21.9% oxygen; and there is another iron oxide that is a red powder which is 70.4% iron and 29.6% oxygen. Adjusting these figures, in the black powder there is about 28 g of oxygen for every 100 g of iron, and in the red powder there is about 42 g of oxygen for every 100 g of iron. 28 and 42 form a ratio of 2:3. Dalton concluded that in these oxides, for every two atoms of iron, there are two or three atoms of oxygen respectively. These substances are known today as iron(II) oxide and iron(III) oxide, and their formulas are FeO and Fe2O3 respectively. Iron(II) oxide''s formula is normally written as FeO, but since it is a crystalline substance we could alternately write it as Fe2O2, and when we contrast that with Fe2O3, the 2:3 ratio for the oxygen is plain to see.');
insert into public.content_chunks (topic_id, title, body, source_name, source_url, license)
select 'atoms-nuclear', 'Atom: Dalton''s law of multiple proportions', 'As a final example, though not using the values in Dalton''s original data: nitrous oxide (N2O) is 63.3% nitrogen and 36.7% oxygen, nitric oxide (NO) is 44.05% nitrogen and 55.95% oxygen, and nitrogen dioxide (NO2) is 29.5% nitrogen and 70.5% oxygen. Adjusting these figures, in nitrous oxide there is 80 g of oxygen for every 140 g of nitrogen, in nitric oxide there is about 160 g of oxygen for every 140 g of nitrogen, and in nitrogen dioxide there is 320 g of oxygen for every 140 g of nitrogen. 80, 160, and 320 form a ratio of 1:2:4.', 'Wikipedia: Atom', 'https://en.wikipedia.org/w/index.php?title=Atom&oldid=1377869405', 'CC BY-SA 4.0. Wikipedia contributors (see page history). Excerpted and split into passages.'
where not exists (select 1 from public.content_chunks where topic_id = 'atoms-nuclear' and body = 'As a final example, though not using the values in Dalton''s original data: nitrous oxide (N2O) is 63.3% nitrogen and 36.7% oxygen, nitric oxide (NO) is 44.05% nitrogen and 55.95% oxygen, and nitrogen dioxide (NO2) is 29.5% nitrogen and 70.5% oxygen. Adjusting these figures, in nitrous oxide there is 80 g of oxygen for every 140 g of nitrogen, in nitric oxide there is about 160 g of oxygen for every 140 g of nitrogen, and in nitrogen dioxide there is 320 g of oxygen for every 140 g of nitrogen. 80, 160, and 320 form a ratio of 1:2:4.');
insert into public.content_chunks (topic_id, title, body, source_name, source_url, license)
select 'atoms-nuclear', 'Electron configuration', 'In atomic physics and quantum chemistry, the electron configuration is the distribution of electrons of an atom or molecule (or other physical structure) in atomic or molecular orbitals. For example, the electron configuration of the neon atom is 1s2 2s2 2p6, meaning that the 1s, 2s, and 2p subshells are occupied by two, two, and six electrons, respectively. Electronic configurations describe each electron as moving independently in an orbital, in an average field created by the nuclei and all the other electrons. Mathematically, configurations are described by Slater determinants or configuration state functions. According to the laws of quantum mechanics, a level of energy is associated with each electron configuration. In certain conditions, electrons are able to move from one configuration to another by the emission or absorption of a quantum of energy, in the form of a photon. Knowledge of the electron configuration of different atoms is useful in understanding the structure of the periodic table of elements, for describing the chemical bonds that hold atoms together, and in understanding the chemical formulas of compounds and the geometries of molecules. In bulk materials, this same idea helps explain the peculiar properties of lasers and semiconductors.', 'Wikipedia: Electron configuration', 'https://en.wikipedia.org/w/index.php?title=Electron_configuration&oldid=1378968605', 'CC BY-SA 4.0. Wikipedia contributors (see page history). Excerpted and split into passages.'
where not exists (select 1 from public.content_chunks where topic_id = 'atoms-nuclear' and body = 'In atomic physics and quantum chemistry, the electron configuration is the distribution of electrons of an atom or molecule (or other physical structure) in atomic or molecular orbitals. For example, the electron configuration of the neon atom is 1s2 2s2 2p6, meaning that the 1s, 2s, and 2p subshells are occupied by two, two, and six electrons, respectively. Electronic configurations describe each electron as moving independently in an orbital, in an average field created by the nuclei and all the other electrons. Mathematically, configurations are described by Slater determinants or configuration state functions. According to the laws of quantum mechanics, a level of energy is associated with each electron configuration. In certain conditions, electrons are able to move from one configuration to another by the emission or absorption of a quantum of energy, in the form of a photon. Knowledge of the electron configuration of different atoms is useful in understanding the structure of the periodic table of elements, for describing the chemical bonds that hold atoms together, and in understanding the chemical formulas of compounds and the geometries of molecules. In bulk materials, this same idea helps explain the peculiar properties of lasers and semiconductors.');
insert into public.content_chunks (topic_id, title, body, source_name, source_url, license)
select 'atoms-nuclear', 'Electron configuration: Shells and subshells', 'Electron configuration was first conceived under the Bohr model of the atom, and it is still common to speak of shells and subshells despite the advances in understanding of the quantum-mechanical nature of electrons. An electron shell is the set of allowed states that share the same principal quantum number, n, that electrons may occupy. In each term of an electron configuration, n is the positive integer that precedes each orbital letter (e.g. helium''s electron configuration is 1s2, therefore n = 1, and the orbital contains two electrons). An atom''s nth electron shell can accommodate 2n2 electrons. For example, the first shell can accommodate two electrons, the second shell eight electrons, the third shell eighteen, and so on. The factor of two arises due to electron spin. Each atomic orbital admits up to two otherwise identical electrons with opposite spin, one with a spin +1⁄2 (usually denoted by an up-arrow) and one with a spin of −1⁄2 (with a down-arrow).', 'Wikipedia: Electron configuration', 'https://en.wikipedia.org/w/index.php?title=Electron_configuration&oldid=1378968605', 'CC BY-SA 4.0. Wikipedia contributors (see page history). Excerpted and split into passages.'
where not exists (select 1 from public.content_chunks where topic_id = 'atoms-nuclear' and body = 'Electron configuration was first conceived under the Bohr model of the atom, and it is still common to speak of shells and subshells despite the advances in understanding of the quantum-mechanical nature of electrons. An electron shell is the set of allowed states that share the same principal quantum number, n, that electrons may occupy. In each term of an electron configuration, n is the positive integer that precedes each orbital letter (e.g. helium''s electron configuration is 1s2, therefore n = 1, and the orbital contains two electrons). An atom''s nth electron shell can accommodate 2n2 electrons. For example, the first shell can accommodate two electrons, the second shell eight electrons, the third shell eighteen, and so on. The factor of two arises due to electron spin. Each atomic orbital admits up to two otherwise identical electrons with opposite spin, one with a spin +1⁄2 (usually denoted by an up-arrow) and one with a spin of −1⁄2 (with a down-arrow).');
insert into public.content_chunks (topic_id, title, body, source_name, source_url, license)
select 'atoms-nuclear', 'Electron configuration: Shells and subshells', 'A subshell is the set of states defined by a common azimuthal quantum number, l, within a shell. The value of l is in the range from 0 to n − 1. The values l = 0, 1, 2, 3 correspond to the s, p, d, and f labels, respectively. For example, the 3d subshell has n = 3 and l = 2. The maximum number of electrons that can be placed in a subshell is given by 2(2l + 1). This gives two electrons in an s subshell, six electrons in a p subshell, and ten electrons in a d subshell. The numbers of electrons that can occupy each shell and each subshell arise from the equations of quantum mechanics, in particular the Pauli exclusion principle, which states that no two electrons in the same atom can have the same values of the four quantum numbers. Exhaustive technical details about the complete quantum mechanical theory of atomic spectra and structure can be found and studied in the basic book of Robert D. Cowan.', 'Wikipedia: Electron configuration', 'https://en.wikipedia.org/w/index.php?title=Electron_configuration&oldid=1378968605', 'CC BY-SA 4.0. Wikipedia contributors (see page history). Excerpted and split into passages.'
where not exists (select 1 from public.content_chunks where topic_id = 'atoms-nuclear' and body = 'A subshell is the set of states defined by a common azimuthal quantum number, l, within a shell. The value of l is in the range from 0 to n − 1. The values l = 0, 1, 2, 3 correspond to the s, p, d, and f labels, respectively. For example, the 3d subshell has n = 3 and l = 2. The maximum number of electrons that can be placed in a subshell is given by 2(2l + 1). This gives two electrons in an s subshell, six electrons in a p subshell, and ten electrons in a d subshell. The numbers of electrons that can occupy each shell and each subshell arise from the equations of quantum mechanics, in particular the Pauli exclusion principle, which states that no two electrons in the same atom can have the same values of the four quantum numbers. Exhaustive technical details about the complete quantum mechanical theory of atomic spectra and structure can be found and studied in the basic book of Robert D. Cowan.');
insert into public.content_chunks (topic_id, title, body, source_name, source_url, license)
select 'atoms-nuclear', 'Electron configuration: Notation', 'Physicists and chemists use a standard notation to indicate the electron configurations of atoms and molecules. For atoms, the notation consists of a sequence of atomic subshell labels (e.g. for phosphorus the sequence 1s, 2s, 2p, 3s, 3p) with the number of electrons assigned to each subshell placed as a superscript. For example, hydrogen has one electron in the s-orbital of the first shell, so its configuration is written 1s1. Lithium has two electrons in the 1s-subshell and one in the (higher-energy) 2s-subshell, so its configuration is written 1s2 2s1 (pronounced "one-s-two, two-s-one"). Phosphorus (atomic number 15) is as follows: 1s2 2s2 2p6 3s2 3p3. It is quite common to see the letters of the orbital labels (s, p, d, f) written in an italic or slanting typeface, although the International Union of Pure and Applied Chemistry (IUPAC) recommends a normal typeface (as used here). The choice of letters originates from a now-obsolete system of categorizing spectral lines as "sharp", "principal", "diffuse" and "fundamental" (or "fine"), based on their observed fine structure: their modern usage indicates orbitals with an azimuthal quantum number, l, of 0, 1, 2 or 3 respectively. After f, the sequence continues alphabetically g, h, i... (l = 4, 5, 6...), skipping j, although orbitals of these types are rarely required.', 'Wikipedia: Electron configuration', 'https://en.wikipedia.org/w/index.php?title=Electron_configuration&oldid=1378968605', 'CC BY-SA 4.0. Wikipedia contributors (see page history). Excerpted and split into passages.'
where not exists (select 1 from public.content_chunks where topic_id = 'atoms-nuclear' and body = 'Physicists and chemists use a standard notation to indicate the electron configurations of atoms and molecules. For atoms, the notation consists of a sequence of atomic subshell labels (e.g. for phosphorus the sequence 1s, 2s, 2p, 3s, 3p) with the number of electrons assigned to each subshell placed as a superscript. For example, hydrogen has one electron in the s-orbital of the first shell, so its configuration is written 1s1. Lithium has two electrons in the 1s-subshell and one in the (higher-energy) 2s-subshell, so its configuration is written 1s2 2s1 (pronounced "one-s-two, two-s-one"). Phosphorus (atomic number 15) is as follows: 1s2 2s2 2p6 3s2 3p3. It is quite common to see the letters of the orbital labels (s, p, d, f) written in an italic or slanting typeface, although the International Union of Pure and Applied Chemistry (IUPAC) recommends a normal typeface (as used here). The choice of letters originates from a now-obsolete system of categorizing spectral lines as "sharp", "principal", "diffuse" and "fundamental" (or "fine"), based on their observed fine structure: their modern usage indicates orbitals with an azimuthal quantum number, l, of 0, 1, 2 or 3 respectively. After f, the sequence continues alphabetically g, h, i... (l = 4, 5, 6...), skipping j, although orbitals of these types are rarely required.');
insert into public.content_chunks (topic_id, title, body, source_name, source_url, license)
select 'atoms-nuclear', 'Electron configuration: Notation', 'The electron configurations of molecules are written in a similar way, except that molecular orbital labels are used instead of atomic orbital labels.', 'Wikipedia: Electron configuration', 'https://en.wikipedia.org/w/index.php?title=Electron_configuration&oldid=1378968605', 'CC BY-SA 4.0. Wikipedia contributors (see page history). Excerpted and split into passages.'
where not exists (select 1 from public.content_chunks where topic_id = 'atoms-nuclear' and body = 'The electron configurations of molecules are written in a similar way, except that molecular orbital labels are used instead of atomic orbital labels.');
insert into public.content_chunks (topic_id, title, body, source_name, source_url, license)
select 'atoms-nuclear', 'Electron configuration: Condensed', 'For atoms with many electrons, this notation can become lengthy and so an abbreviated notation is used. The electron configuration can be visualized as the core electrons, equivalent to the noble gas of the preceding period, and the valence electrons: each element in a period differs only by the last few subshells. Phosphorus, for instance, is in the third period. It differs from the second-period neon, whose configuration is 1s2 2s2 2p6, only by the presence of a third shell. The portion of its configuration that is equivalent to neon is abbreviated as [Ne], allowing the configuration of phosphorus to be written as [Ne] 3s2 3p3 rather than writing out the details of the configuration of neon explicitly. This convention is useful as it is the electrons in the outermost shell that most determine the chemistry of the element.', 'Wikipedia: Electron configuration', 'https://en.wikipedia.org/w/index.php?title=Electron_configuration&oldid=1378968605', 'CC BY-SA 4.0. Wikipedia contributors (see page history). Excerpted and split into passages.'
where not exists (select 1 from public.content_chunks where topic_id = 'atoms-nuclear' and body = 'For atoms with many electrons, this notation can become lengthy and so an abbreviated notation is used. The electron configuration can be visualized as the core electrons, equivalent to the noble gas of the preceding period, and the valence electrons: each element in a period differs only by the last few subshells. Phosphorus, for instance, is in the third period. It differs from the second-period neon, whose configuration is 1s2 2s2 2p6, only by the presence of a third shell. The portion of its configuration that is equivalent to neon is abbreviated as [Ne], allowing the configuration of phosphorus to be written as [Ne] 3s2 3p3 rather than writing out the details of the configuration of neon explicitly. This convention is useful as it is the electrons in the outermost shell that most determine the chemistry of the element.');
insert into public.content_chunks (topic_id, title, body, source_name, source_url, license)
select 'atoms-nuclear', 'Electron configuration: Order', 'For a given configuration, the order of writing the orbitals is not completely fixed since only the orbital occupancies have physical significance. For example, the electron configuration of the titanium ground state can be written as either [Ar] 4s2 3d2 or [Ar] 3d2 4s2. The first notation follows the order based on the Madelung rule for the configurations of neutral atoms; 4s is filled before 3d in the sequence Ar, K, Ca, Sc, Ti. The second notation groups all orbitals with the same value of n together, corresponding to the "spectroscopic" order of orbital energies that is the reverse of the order in which electrons are removed from a given atom to form positive ions; 3d is filled before 4s in the sequence Ti4+, Ti3+, Ti2+, Ti+, Ti.', 'Wikipedia: Electron configuration', 'https://en.wikipedia.org/w/index.php?title=Electron_configuration&oldid=1378968605', 'CC BY-SA 4.0. Wikipedia contributors (see page history). Excerpted and split into passages.'
where not exists (select 1 from public.content_chunks where topic_id = 'atoms-nuclear' and body = 'For a given configuration, the order of writing the orbitals is not completely fixed since only the orbital occupancies have physical significance. For example, the electron configuration of the titanium ground state can be written as either [Ar] 4s2 3d2 or [Ar] 3d2 4s2. The first notation follows the order based on the Madelung rule for the configurations of neutral atoms; 4s is filled before 3d in the sequence Ar, K, Ca, Sc, Ti. The second notation groups all orbitals with the same value of n together, corresponding to the "spectroscopic" order of orbital energies that is the reverse of the order in which electrons are removed from a given atom to form positive ions; 3d is filled before 4s in the sequence Ti4+, Ti3+, Ti2+, Ti+, Ti.');
insert into public.content_chunks (topic_id, title, body, source_name, source_url, license)
select 'atoms-nuclear', 'Electron configuration: Implied Values', 'The superscript 1 for a singly occupied subshell is not compulsory; for example, aluminium may be written as either [Ne] 3s2 3p1 or [Ne] 3s2 3p. In atoms where a subshell is unoccupied despite higher subshells being occupied (as is the case in some ions, as well as certain neutral atoms shown to deviate from the Madelung rule), the empty subshell is either denoted with a superscript 0 or left out altogether. For example, neutral palladium may be written as either [Kr] 4d10 5s0 or simply [Kr] 4d10, and the lanthanum(III) ion may be written as either [Xe] 4f0 or simply [Xe].', 'Wikipedia: Electron configuration', 'https://en.wikipedia.org/w/index.php?title=Electron_configuration&oldid=1378968605', 'CC BY-SA 4.0. Wikipedia contributors (see page history). Excerpted and split into passages.'
where not exists (select 1 from public.content_chunks where topic_id = 'atoms-nuclear' and body = 'The superscript 1 for a singly occupied subshell is not compulsory; for example, aluminium may be written as either [Ne] 3s2 3p1 or [Ne] 3s2 3p. In atoms where a subshell is unoccupied despite higher subshells being occupied (as is the case in some ions, as well as certain neutral atoms shown to deviate from the Madelung rule), the empty subshell is either denoted with a superscript 0 or left out altogether. For example, neutral palladium may be written as either [Kr] 4d10 5s0 or simply [Kr] 4d10, and the lanthanum(III) ion may be written as either [Xe] 4f0 or simply [Xe].');
insert into public.content_chunks (topic_id, title, body, source_name, source_url, license)
select 'atoms-nuclear', 'Quantum number', 'In quantum physics and chemistry, quantum numbers are quantities that characterize the possible states of the system. To fully specify the state of the electron in a hydrogen atom, four quantum numbers are needed. The traditional set of quantum numbers includes the principal, azimuthal, magnetic, and spin quantum numbers. To describe other systems, different quantum numbers are required. For subatomic particles, one needs to introduce new quantum numbers, such as the flavour of quarks, which have no classical correspondence. Quantum numbers are closely related to eigenvalues of observables. When the corresponding observable commutes with the Hamiltonian of the system, the quantum number is said to be "good", and acts as a constant of motion in the quantum dynamics.', 'Wikipedia: Quantum number', 'https://en.wikipedia.org/w/index.php?title=Quantum_number&oldid=1375963102', 'CC BY-SA 4.0. Wikipedia contributors (see page history). Excerpted and split into passages.'
where not exists (select 1 from public.content_chunks where topic_id = 'atoms-nuclear' and body = 'In quantum physics and chemistry, quantum numbers are quantities that characterize the possible states of the system. To fully specify the state of the electron in a hydrogen atom, four quantum numbers are needed. The traditional set of quantum numbers includes the principal, azimuthal, magnetic, and spin quantum numbers. To describe other systems, different quantum numbers are required. For subatomic particles, one needs to introduce new quantum numbers, such as the flavour of quarks, which have no classical correspondence. Quantum numbers are closely related to eigenvalues of observables. When the corresponding observable commutes with the Hamiltonian of the system, the quantum number is said to be "good", and acts as a constant of motion in the quantum dynamics.');
insert into public.content_chunks (topic_id, title, body, source_name, source_url, license)
select 'atoms-nuclear', 'Quantum number: Properties', 'The tally of quantum numbers varies from system to system and has no universal answer. Hence these parameters must be found for each system to be analyzed. A quantized system requires at least one quantum number. The dynamics (i.e. time evolution) of any quantum system are described by a quantum operator in the form of a Hamiltonian, H. There is one quantum number of the system corresponding to the system''s energy; i.e., one of the eigenvalues of the Hamiltonian. There is also one quantum number for each linearly independent operator O that commutes with the Hamiltonian. A complete set of commuting observables (CSCO) that commute with the Hamiltonian characterizes the system with all its quantum numbers. There is a one-to-one relationship between the quantum numbers and the operators of the CSCO, with each quantum number taking one of the eigenvalues of its corresponding operator. As a result of the different basis that may be arbitrarily chosen to form a complete set of commuting operators, different sets of quantum numbers may be used for the description of the same system in different situations.', 'Wikipedia: Quantum number', 'https://en.wikipedia.org/w/index.php?title=Quantum_number&oldid=1375963102', 'CC BY-SA 4.0. Wikipedia contributors (see page history). Excerpted and split into passages.'
where not exists (select 1 from public.content_chunks where topic_id = 'atoms-nuclear' and body = 'The tally of quantum numbers varies from system to system and has no universal answer. Hence these parameters must be found for each system to be analyzed. A quantized system requires at least one quantum number. The dynamics (i.e. time evolution) of any quantum system are described by a quantum operator in the form of a Hamiltonian, H. There is one quantum number of the system corresponding to the system''s energy; i.e., one of the eigenvalues of the Hamiltonian. There is also one quantum number for each linearly independent operator O that commutes with the Hamiltonian. A complete set of commuting observables (CSCO) that commute with the Hamiltonian characterizes the system with all its quantum numbers. There is a one-to-one relationship between the quantum numbers and the operators of the CSCO, with each quantum number taking one of the eigenvalues of its corresponding operator. As a result of the different basis that may be arbitrarily chosen to form a complete set of commuting operators, different sets of quantum numbers may be used for the description of the same system in different situations.');
insert into public.content_chunks (topic_id, title, body, source_name, source_url, license)
select 'atoms-nuclear', 'Quantum number: Good quantum numbers', 'A specific category of quantum numbers are called "good" quantum numbers; they correspond to eigenvalues of operators that commute with the Hamiltonian, quantities that can be known with precision at the same time as the system''s energy. Specifically, observables that commute with the Hamiltonian are simultaneously diagonalizable with it and so the eigenvalues and the energy (eigenvalues of the Hamiltonian) are not limited by an uncertainty relation arising from non-commutativity. Together, a specification of all of the quantum numbers of a quantum system fully characterize a basis state of the system, and can in principle be measured together. Many observables have discrete spectra (sets of eigenvalues) in quantum mechanics, so the quantities can only be measured in discrete values. In particular, this leads to quantum numbers that take values in discrete sets of integers or half-integers; although they could approach infinity in some cases.', 'Wikipedia: Quantum number', 'https://en.wikipedia.org/w/index.php?title=Quantum_number&oldid=1375963102', 'CC BY-SA 4.0. Wikipedia contributors (see page history). Excerpted and split into passages.'
where not exists (select 1 from public.content_chunks where topic_id = 'atoms-nuclear' and body = 'A specific category of quantum numbers are called "good" quantum numbers; they correspond to eigenvalues of operators that commute with the Hamiltonian, quantities that can be known with precision at the same time as the system''s energy. Specifically, observables that commute with the Hamiltonian are simultaneously diagonalizable with it and so the eigenvalues and the energy (eigenvalues of the Hamiltonian) are not limited by an uncertainty relation arising from non-commutativity. Together, a specification of all of the quantum numbers of a quantum system fully characterize a basis state of the system, and can in principle be measured together. Many observables have discrete spectra (sets of eigenvalues) in quantum mechanics, so the quantities can only be measured in discrete values. In particular, this leads to quantum numbers that take values in discrete sets of integers or half-integers; although they could approach infinity in some cases.');
insert into public.content_chunks (topic_id, title, body, source_name, source_url, license)
select 'atoms-nuclear', 'Quantum number: Electron in a hydrogen-like atom', 'Four quantum numbers can describe an electron energy level in a hydrogen-like atom completely: These quantum numbers are also used in the classical description of nuclear particle states (e.g. protons and neutrons). A quantum description of molecular orbitals requires other quantum numbers, because the symmetries of the molecular system are different.', 'Wikipedia: Quantum number', 'https://en.wikipedia.org/w/index.php?title=Quantum_number&oldid=1375963102', 'CC BY-SA 4.0. Wikipedia contributors (see page history). Excerpted and split into passages.'
where not exists (select 1 from public.content_chunks where topic_id = 'atoms-nuclear' and body = 'Four quantum numbers can describe an electron energy level in a hydrogen-like atom completely: These quantum numbers are also used in the classical description of nuclear particle states (e.g. protons and neutrons). A quantum description of molecular orbitals requires other quantum numbers, because the symmetries of the molecular system are different.');
insert into public.content_chunks (topic_id, title, body, source_name, source_url, license)
select 'atoms-nuclear', 'Quantum number: Principal quantum number', 'The principal quantum number describes the electron shell of an atom. The value of n ranges from 1 to the shell containing the outermost electron of that atom, that is For example, in caesium (Cs), the outermost valence electron is in the shell with energy level 6, so an electron in caesium can have an n value from 1 to 6. The average distance between the electron and the nucleus increases with n.', 'Wikipedia: Quantum number', 'https://en.wikipedia.org/w/index.php?title=Quantum_number&oldid=1375963102', 'CC BY-SA 4.0. Wikipedia contributors (see page history). Excerpted and split into passages.'
where not exists (select 1 from public.content_chunks where topic_id = 'atoms-nuclear' and body = 'The principal quantum number describes the electron shell of an atom. The value of n ranges from 1 to the shell containing the outermost electron of that atom, that is For example, in caesium (Cs), the outermost valence electron is in the shell with energy level 6, so an electron in caesium can have an n value from 1 to 6. The average distance between the electron and the nucleus increases with n.');
insert into public.content_chunks (topic_id, title, body, source_name, source_url, license)
select 'atoms-nuclear', 'Quantum number: Azimuthal quantum number', 'The azimuthal quantum number, also known as the orbital angular momentum quantum number, describes the subshell, and gives the magnitude of the orbital angular momentum through the relation In chemistry and spectroscopy, ℓ = 0 is called s orbital, ℓ = 1, p orbital, ℓ = 2, d orbital, and ℓ = 3, f orbital. The value of ℓ ranges from 0 to n − 1, so the first p orbital (ℓ = 1) appears in the second electron shell (n = 2), the first d orbital (ℓ = 2) appears in the third shell (n = 3), and so on: A quantum number beginning in n = 3, ℓ = 0, describes an electron in the s orbital of the third electron shell of an atom. In chemistry, this quantum number is very important, since it specifies the shape of an atomic orbital and strongly influences chemical bonds and bond angles. The azimuthal quantum number can also denote the number of angular nodes present in an orbital. For example, for p orbitals, ℓ = 1 and thus the amount of angular nodes in a p orbital is 1.', 'Wikipedia: Quantum number', 'https://en.wikipedia.org/w/index.php?title=Quantum_number&oldid=1375963102', 'CC BY-SA 4.0. Wikipedia contributors (see page history). Excerpted and split into passages.'
where not exists (select 1 from public.content_chunks where topic_id = 'atoms-nuclear' and body = 'The azimuthal quantum number, also known as the orbital angular momentum quantum number, describes the subshell, and gives the magnitude of the orbital angular momentum through the relation In chemistry and spectroscopy, ℓ = 0 is called s orbital, ℓ = 1, p orbital, ℓ = 2, d orbital, and ℓ = 3, f orbital. The value of ℓ ranges from 0 to n − 1, so the first p orbital (ℓ = 1) appears in the second electron shell (n = 2), the first d orbital (ℓ = 2) appears in the third shell (n = 3), and so on: A quantum number beginning in n = 3, ℓ = 0, describes an electron in the s orbital of the third electron shell of an atom. In chemistry, this quantum number is very important, since it specifies the shape of an atomic orbital and strongly influences chemical bonds and bond angles. The azimuthal quantum number can also denote the number of angular nodes present in an orbital. For example, for p orbitals, ℓ = 1 and thus the amount of angular nodes in a p orbital is 1.');
insert into public.content_chunks (topic_id, title, body, source_name, source_url, license)
select 'atoms-nuclear', 'Quantum number: Magnetic quantum number', 'The magnetic quantum number describes the specific orbital within the subshell, and yields the projection of the orbital angular momentum along a specified axis: The values of mℓ range from −ℓ to ℓ, with integer intervals. The s subshell (ℓ = 0) contains only one orbital, and therefore the mℓ of an electron in an s orbital will always be 0. The p subshell (ℓ = 1) contains three orbitals, so the mℓ of an electron in a p orbital will be −1, 0, or 1. The d subshell (ℓ = 2) contains five orbitals, with mℓ values of −2, −1, 0, 1, and 2.', 'Wikipedia: Quantum number', 'https://en.wikipedia.org/w/index.php?title=Quantum_number&oldid=1375963102', 'CC BY-SA 4.0. Wikipedia contributors (see page history). Excerpted and split into passages.'
where not exists (select 1 from public.content_chunks where topic_id = 'atoms-nuclear' and body = 'The magnetic quantum number describes the specific orbital within the subshell, and yields the projection of the orbital angular momentum along a specified axis: The values of mℓ range from −ℓ to ℓ, with integer intervals. The s subshell (ℓ = 0) contains only one orbital, and therefore the mℓ of an electron in an s orbital will always be 0. The p subshell (ℓ = 1) contains three orbitals, so the mℓ of an electron in a p orbital will be −1, 0, or 1. The d subshell (ℓ = 2) contains five orbitals, with mℓ values of −2, −1, 0, 1, and 2.');
insert into public.content_chunks (topic_id, title, body, source_name, source_url, license)
select 'atoms-nuclear', 'Quantum number: Spin magnetic quantum number', 'The spin magnetic quantum number describes the intrinsic spin angular momentum of the electron within each orbital and gives the projection of the spin angular momentum S along the specified axis: In general, the values of ms range from −s to s, where s is the spin quantum number, associated with the magnitude of particle''s intrinsic spin angular momentum: An electron state has spin number s = ⁠1/2⁠, consequently ms will be +⁠1/2⁠ ("spin up") or −⁠1/2⁠ ("spin down) states. Since electron are fermions, they obey the Pauli exclusion principle: each electron state must have different quantum numbers. Therefore, every orbital will be occupied with at most two electrons, one for each spin state.', 'Wikipedia: Quantum number', 'https://en.wikipedia.org/w/index.php?title=Quantum_number&oldid=1375963102', 'CC BY-SA 4.0. Wikipedia contributors (see page history). Excerpted and split into passages.'
where not exists (select 1 from public.content_chunks where topic_id = 'atoms-nuclear' and body = 'The spin magnetic quantum number describes the intrinsic spin angular momentum of the electron within each orbital and gives the projection of the spin angular momentum S along the specified axis: In general, the values of ms range from −s to s, where s is the spin quantum number, associated with the magnitude of particle''s intrinsic spin angular momentum: An electron state has spin number s = ⁠1/2⁠, consequently ms will be +⁠1/2⁠ ("spin up") or −⁠1/2⁠ ("spin down) states. Since electron are fermions, they obey the Pauli exclusion principle: each electron state must have different quantum numbers. Therefore, every orbital will be occupied with at most two electrons, one for each spin state.');
insert into public.content_chunks (topic_id, title, body, source_name, source_url, license)
select 'atoms-nuclear', 'Photoelectric effect', 'The photoelectric effect is the emission of electrons from a material caused by electromagnetic radiation such as ultraviolet light. Electrons emitted in this manner are called photoelectrons. The phenomenon is studied in condensed matter physics, solid state, and quantum chemistry to draw inferences about the properties of atoms, molecules and solids. The effect has found use in electronic devices specialized for light detection and precisely timed electron emission. The experimental results disagree with classical electromagnetism, which predicts that continuous light waves transfer energy to electrons, which would then be emitted when they accumulate enough energy. An alteration in the intensity of light would theoretically change the kinetic energy of the emitted electrons, with sufficiently dim light resulting in a delayed emission. The experimental results instead show that electrons are dislodged only when the light exceeds a certain frequency—regardless of the light''s intensity or duration of exposure. Because a low-frequency beam at a high intensity does not build up the energy required to produce photoelectrons, as would be the case if light''s energy accumulated over time from a continuous wave, Albert Einstein proposed that a beam of light is not a wave propagating through space, but discrete energy packets, which were later popularised as photons by Gilbert N. Lewis.', 'Wikipedia: Photoelectric effect', 'https://en.wikipedia.org/w/index.php?title=Photoelectric_effect&oldid=1381145808', 'CC BY-SA 4.0. Wikipedia contributors (see page history). Excerpted and split into passages.'
where not exists (select 1 from public.content_chunks where topic_id = 'atoms-nuclear' and body = 'The photoelectric effect is the emission of electrons from a material caused by electromagnetic radiation such as ultraviolet light. Electrons emitted in this manner are called photoelectrons. The phenomenon is studied in condensed matter physics, solid state, and quantum chemistry to draw inferences about the properties of atoms, molecules and solids. The effect has found use in electronic devices specialized for light detection and precisely timed electron emission. The experimental results disagree with classical electromagnetism, which predicts that continuous light waves transfer energy to electrons, which would then be emitted when they accumulate enough energy. An alteration in the intensity of light would theoretically change the kinetic energy of the emitted electrons, with sufficiently dim light resulting in a delayed emission. The experimental results instead show that electrons are dislodged only when the light exceeds a certain frequency—regardless of the light''s intensity or duration of exposure. Because a low-frequency beam at a high intensity does not build up the energy required to produce photoelectrons, as would be the case if light''s energy accumulated over time from a continuous wave, Albert Einstein proposed that a beam of light is not a wave propagating through space, but discrete energy packets, which were later popularised as photons by Gilbert N. Lewis.');
insert into public.content_chunks (topic_id, title, body, source_name, source_url, license)
select 'atoms-nuclear', 'Photoelectric effect', 'Emission of conduction electrons from typical metals requires a few electron-volt (eV) light quanta, corresponding to short-wavelength visible or ultraviolet light. In extreme cases, emissions are induced with photons approaching zero energy, like in systems with negative electron affinity and the emission from excited states, or a few hundred keV photons for core electrons in elements with a high atomic number. Study of the photoelectric effect led to important steps in understanding the quantum nature of light and electrons and influenced the formation of the concept of wave–particle duality. Other phenomena where light affects the movement of electric charges include the photoconductive effect, the photovoltaic effect, and the photoelectrochemical effect.', 'Wikipedia: Photoelectric effect', 'https://en.wikipedia.org/w/index.php?title=Photoelectric_effect&oldid=1381145808', 'CC BY-SA 4.0. Wikipedia contributors (see page history). Excerpted and split into passages.'
where not exists (select 1 from public.content_chunks where topic_id = 'atoms-nuclear' and body = 'Emission of conduction electrons from typical metals requires a few electron-volt (eV) light quanta, corresponding to short-wavelength visible or ultraviolet light. In extreme cases, emissions are induced with photons approaching zero energy, like in systems with negative electron affinity and the emission from excited states, or a few hundred keV photons for core electrons in elements with a high atomic number. Study of the photoelectric effect led to important steps in understanding the quantum nature of light and electrons and influenced the formation of the concept of wave–particle duality. Other phenomena where light affects the movement of electric charges include the photoconductive effect, the photovoltaic effect, and the photoelectrochemical effect.');
insert into public.content_chunks (topic_id, title, body, source_name, source_url, license)
select 'atoms-nuclear', 'Photoelectric effect: Emission mechanism', 'The photons of a light beam have a characteristic energy, called photon energy, which is proportional to the frequency of the light. In the photoemission process, when an electron within some material absorbs the energy of a photon and acquires more energy than its binding energy, it is likely to be ejected. If the photon energy is too low, the electron is unable to escape the material. Since an increase in the intensity of low-frequency light will only increase the number of low-energy photons, this change in intensity will not create any single photon with enough energy to dislodge an electron. Moreover, the energy of the emitted electrons will not depend on the intensity of the incoming light of a given frequency, but only on the energy of the individual photons.', 'Wikipedia: Photoelectric effect', 'https://en.wikipedia.org/w/index.php?title=Photoelectric_effect&oldid=1381145808', 'CC BY-SA 4.0. Wikipedia contributors (see page history). Excerpted and split into passages.'
where not exists (select 1 from public.content_chunks where topic_id = 'atoms-nuclear' and body = 'The photons of a light beam have a characteristic energy, called photon energy, which is proportional to the frequency of the light. In the photoemission process, when an electron within some material absorbs the energy of a photon and acquires more energy than its binding energy, it is likely to be ejected. If the photon energy is too low, the electron is unable to escape the material. Since an increase in the intensity of low-frequency light will only increase the number of low-energy photons, this change in intensity will not create any single photon with enough energy to dislodge an electron. Moreover, the energy of the emitted electrons will not depend on the intensity of the incoming light of a given frequency, but only on the energy of the individual photons.');
insert into public.content_chunks (topic_id, title, body, source_name, source_url, license)
select 'atoms-nuclear', 'Photoelectric effect: Emission mechanism', 'While free electrons can absorb any energy when irradiated as long as this is followed by an immediate re-emission, like in the Compton effect, in quantum systems all of the energy from one photon is absorbed—if the process is allowed by quantum mechanics—or none at all. Part of the acquired energy is used to liberate the electron from its atomic binding, and the rest contributes to the electron''s kinetic energy as a free particle. Because electrons in a material occupy many different quantum states with different binding energies, and because they can sustain energy losses on their way out of the material, the emitted electrons will have a range of kinetic energies. The electrons from the highest occupied states will have the highest kinetic energy. In metals, those electrons will be emitted from the Fermi level. When the photoelectron is emitted into a solid rather than into a vacuum, the term internal photoemission is often used, and emission into a vacuum is distinguished as external photoemission.', 'Wikipedia: Photoelectric effect', 'https://en.wikipedia.org/w/index.php?title=Photoelectric_effect&oldid=1381145808', 'CC BY-SA 4.0. Wikipedia contributors (see page history). Excerpted and split into passages.'
where not exists (select 1 from public.content_chunks where topic_id = 'atoms-nuclear' and body = 'While free electrons can absorb any energy when irradiated as long as this is followed by an immediate re-emission, like in the Compton effect, in quantum systems all of the energy from one photon is absorbed—if the process is allowed by quantum mechanics—or none at all. Part of the acquired energy is used to liberate the electron from its atomic binding, and the rest contributes to the electron''s kinetic energy as a free particle. Because electrons in a material occupy many different quantum states with different binding energies, and because they can sustain energy losses on their way out of the material, the emitted electrons will have a range of kinetic energies. The electrons from the highest occupied states will have the highest kinetic energy. In metals, those electrons will be emitted from the Fermi level. When the photoelectron is emitted into a solid rather than into a vacuum, the term internal photoemission is often used, and emission into a vacuum is distinguished as external photoemission.');
insert into public.content_chunks (topic_id, title, body, source_name, source_url, license)
select 'atoms-nuclear', 'Photoelectric effect: Experimental observation of photoelectric emission', 'Even though photoemission can occur from any material, it is most readily observed from metals and other conductors. This is because the process produces a charge imbalance which, if not neutralized by current flow, results in the increasing potential barrier until the emission completely ceases. The energy barrier to photoemission is usually increased by nonconductive oxide layers on metal surfaces, so most practical experiments and devices based on the photoelectric effect use clean metal surfaces in evacuated tubes. Vacuum also helps observing the electrons since it prevents gases from impeding their flow between the electrodes. Sunlight is an inconsistent and variable source of ultraviolet light. Cloud cover, ozone concentration, altitude, and surface reflection all alter the amount of UV. Laboratory sources of UV are based on xenon arc lamps or, for more uniform but weaker light, fluorescent lamps. The classical setup to observe the photoelectric effect includes a light source, a set of filters to monochromatize the light, a vacuum tube transparent to ultraviolet light, an emitting electrode (E) exposed to the light, and a collector (C) whose voltage VC can be externally controlled.', 'Wikipedia: Photoelectric effect', 'https://en.wikipedia.org/w/index.php?title=Photoelectric_effect&oldid=1381145808', 'CC BY-SA 4.0. Wikipedia contributors (see page history). Excerpted and split into passages.'
where not exists (select 1 from public.content_chunks where topic_id = 'atoms-nuclear' and body = 'Even though photoemission can occur from any material, it is most readily observed from metals and other conductors. This is because the process produces a charge imbalance which, if not neutralized by current flow, results in the increasing potential barrier until the emission completely ceases. The energy barrier to photoemission is usually increased by nonconductive oxide layers on metal surfaces, so most practical experiments and devices based on the photoelectric effect use clean metal surfaces in evacuated tubes. Vacuum also helps observing the electrons since it prevents gases from impeding their flow between the electrodes. Sunlight is an inconsistent and variable source of ultraviolet light. Cloud cover, ozone concentration, altitude, and surface reflection all alter the amount of UV. Laboratory sources of UV are based on xenon arc lamps or, for more uniform but weaker light, fluorescent lamps. The classical setup to observe the photoelectric effect includes a light source, a set of filters to monochromatize the light, a vacuum tube transparent to ultraviolet light, an emitting electrode (E) exposed to the light, and a collector (C) whose voltage VC can be externally controlled.');
insert into public.content_chunks (topic_id, title, body, source_name, source_url, license)
select 'atoms-nuclear', 'Photoelectric effect: Experimental observation of photoelectric emission', 'A positive external voltage is used to direct the photoemitted electrons onto the collector. If the frequency and the intensity of the incident radiation are fixed, the photoelectric current I increases with an increase in the positive voltage, as more and more electrons are directed onto the electrode. When no additional photoelectrons can be collected, the photoelectric current attains a saturation value. This current can only increase with the increase of the intensity of light. An increasing negative voltage prevents all but the highest-energy electrons from reaching the collector. When no current is observed through the tube, the negative voltage has reached the value that is high enough to slow down and stop the most energetic photoelectrons of kinetic energy Kmax. This value of the retarding voltage is called the stopping potential or cut off potential Vo. Since the work done by the retarding potential in stopping the electron of charge e is eVo, the following must hold eVo = Kmax. The current-voltage curve is sigmoidal, but its exact shape depends on the experimental geometry and the electrode material properties.', 'Wikipedia: Photoelectric effect', 'https://en.wikipedia.org/w/index.php?title=Photoelectric_effect&oldid=1381145808', 'CC BY-SA 4.0. Wikipedia contributors (see page history). Excerpted and split into passages.'
where not exists (select 1 from public.content_chunks where topic_id = 'atoms-nuclear' and body = 'A positive external voltage is used to direct the photoemitted electrons onto the collector. If the frequency and the intensity of the incident radiation are fixed, the photoelectric current I increases with an increase in the positive voltage, as more and more electrons are directed onto the electrode. When no additional photoelectrons can be collected, the photoelectric current attains a saturation value. This current can only increase with the increase of the intensity of light. An increasing negative voltage prevents all but the highest-energy electrons from reaching the collector. When no current is observed through the tube, the negative voltage has reached the value that is high enough to slow down and stop the most energetic photoelectrons of kinetic energy Kmax. This value of the retarding voltage is called the stopping potential or cut off potential Vo. Since the work done by the retarding potential in stopping the electron of charge e is eVo, the following must hold eVo = Kmax. The current-voltage curve is sigmoidal, but its exact shape depends on the experimental geometry and the electrode material properties.');
insert into public.content_chunks (topic_id, title, body, source_name, source_url, license)
select 'atoms-nuclear', 'Photoelectric effect: Experimental observation of photoelectric emission', 'For a given metal surface, there exists a certain minimum frequency of incident radiation below which no photoelectrons are emitted. This frequency is called the threshold frequency. Increasing the frequency of the incident beam increases the maximum kinetic energy of the emitted photoelectrons, and the stopping voltage has to increase. The number of emitted electrons may also change because the probability that each photon results in an emitted electron is a function of photon energy. An increase in the intensity of the same monochromatic light (so long as the intensity is not too high), which is proportional to the number of photons impinging on the surface in a given time, increases the rate at which electrons are ejected—the photoelectric current I—but the kinetic energy of the photoelectrons and the stopping voltage remain the same. For a given metal and frequency of incident radiation, the rate at which photoelectrons are ejected is directly proportional to the intensity of the incident light.', 'Wikipedia: Photoelectric effect', 'https://en.wikipedia.org/w/index.php?title=Photoelectric_effect&oldid=1381145808', 'CC BY-SA 4.0. Wikipedia contributors (see page history). Excerpted and split into passages.'
where not exists (select 1 from public.content_chunks where topic_id = 'atoms-nuclear' and body = 'For a given metal surface, there exists a certain minimum frequency of incident radiation below which no photoelectrons are emitted. This frequency is called the threshold frequency. Increasing the frequency of the incident beam increases the maximum kinetic energy of the emitted photoelectrons, and the stopping voltage has to increase. The number of emitted electrons may also change because the probability that each photon results in an emitted electron is a function of photon energy. An increase in the intensity of the same monochromatic light (so long as the intensity is not too high), which is proportional to the number of photons impinging on the surface in a given time, increases the rate at which electrons are ejected—the photoelectric current I—but the kinetic energy of the photoelectrons and the stopping voltage remain the same. For a given metal and frequency of incident radiation, the rate at which photoelectrons are ejected is directly proportional to the intensity of the incident light.');
insert into public.content_chunks (topic_id, title, body, source_name, source_url, license)
select 'atoms-nuclear', 'Photoelectric effect: Experimental observation of photoelectric emission', 'The time lag between the incidence of radiation and the emission of a photoelectron is very small, less than 10−9 second. Angular distribution of the photoelectrons is highly dependent on polarization (the direction of the electric field) of the incident light, as well as the emitting material''s quantum properties such as atomic and molecular orbital symmetries and the electronic band structure of crystalline solids. In materials without macroscopic order, the distribution of electrons tends to peak in the direction of polarization of linearly polarized light. The experimental technique that can measure these distributions to infer the material''s properties is angle-resolved photoemission spectroscopy.', 'Wikipedia: Photoelectric effect', 'https://en.wikipedia.org/w/index.php?title=Photoelectric_effect&oldid=1381145808', 'CC BY-SA 4.0. Wikipedia contributors (see page history). Excerpted and split into passages.'
where not exists (select 1 from public.content_chunks where topic_id = 'atoms-nuclear' and body = 'The time lag between the incidence of radiation and the emission of a photoelectron is very small, less than 10−9 second. Angular distribution of the photoelectrons is highly dependent on polarization (the direction of the electric field) of the incident light, as well as the emitting material''s quantum properties such as atomic and molecular orbital symmetries and the electronic band structure of crystalline solids. In materials without macroscopic order, the distribution of electrons tends to peak in the direction of polarization of linearly polarized light. The experimental technique that can measure these distributions to infer the material''s properties is angle-resolved photoemission spectroscopy.');
insert into public.content_chunks (topic_id, title, body, source_name, source_url, license)
select 'atoms-nuclear', 'Radioactive decay', 'Radioactive decay (also known as nuclear decay, radioactivity, radioactive disintegration, or nuclear disintegration) is the process by which an unstable atomic nucleus loses energy by radiation. A material containing unstable nuclei is considered radioactive. Three of the most common types of decay are alpha, beta, and gamma decay. The weak force is the mechanism that is responsible for beta decay, while the other two are governed by the electromagnetic and nuclear forces. Radioactive decay is a random process at the level of single atoms. According to quantum theory, it is impossible to predict when a particular atom will decay, regardless of how long the atom has existed. However, for a significant number of identical atoms, the overall decay rate can be expressed as a decay constant or as a half-life. The half-lives of radioactive isotopes have a huge range: from nearly instantaneous to far longer than the age of the universe. The decaying nucleus is called the parent radionuclide (or parent radioisotope), and the process produces at least one daughter nuclide. Except for gamma decay or internal conversion from a nuclear excited state, the decay is a nuclear transmutation resulting in a daughter containing a different number of protons or neutrons (or both). When the number of protons changes, an atom of a different chemical element is created.', 'Wikipedia: Radioactive decay', 'https://en.wikipedia.org/w/index.php?title=Radioactive_decay&oldid=1381429181', 'CC BY-SA 4.0. Wikipedia contributors (see page history). Excerpted and split into passages.'
where not exists (select 1 from public.content_chunks where topic_id = 'atoms-nuclear' and body = 'Radioactive decay (also known as nuclear decay, radioactivity, radioactive disintegration, or nuclear disintegration) is the process by which an unstable atomic nucleus loses energy by radiation. A material containing unstable nuclei is considered radioactive. Three of the most common types of decay are alpha, beta, and gamma decay. The weak force is the mechanism that is responsible for beta decay, while the other two are governed by the electromagnetic and nuclear forces. Radioactive decay is a random process at the level of single atoms. According to quantum theory, it is impossible to predict when a particular atom will decay, regardless of how long the atom has existed. However, for a significant number of identical atoms, the overall decay rate can be expressed as a decay constant or as a half-life. The half-lives of radioactive isotopes have a huge range: from nearly instantaneous to far longer than the age of the universe. The decaying nucleus is called the parent radionuclide (or parent radioisotope), and the process produces at least one daughter nuclide. Except for gamma decay or internal conversion from a nuclear excited state, the decay is a nuclear transmutation resulting in a daughter containing a different number of protons or neutrons (or both). When the number of protons changes, an atom of a different chemical element is created.');
insert into public.content_chunks (topic_id, title, body, source_name, source_url, license)
select 'atoms-nuclear', 'Radioactive decay', 'There are 28 naturally occurring chemical elements on Earth that are radioactive, consisting of 35 radionuclides (seven elements have two different radionuclides each) that date before the time of formation of the Solar System. These 35 are known as primordial radionuclides. Well-known examples are uranium and thorium, but also included are naturally occurring long-lived radioisotopes, such as potassium-40. Each of the heavy primordial radionuclides participates in one of the four decay chains.', 'Wikipedia: Radioactive decay', 'https://en.wikipedia.org/w/index.php?title=Radioactive_decay&oldid=1381429181', 'CC BY-SA 4.0. Wikipedia contributors (see page history). Excerpted and split into passages.'
where not exists (select 1 from public.content_chunks where topic_id = 'atoms-nuclear' and body = 'There are 28 naturally occurring chemical elements on Earth that are radioactive, consisting of 35 radionuclides (seven elements have two different radionuclides each) that date before the time of formation of the Solar System. These 35 are known as primordial radionuclides. Well-known examples are uranium and thorium, but also included are naturally occurring long-lived radioisotopes, such as potassium-40. Each of the heavy primordial radionuclides participates in one of the four decay chains.');
insert into public.content_chunks (topic_id, title, body, source_name, source_url, license)
select 'atoms-nuclear', 'Radioactive decay: History of discovery', 'Henri Poincaré laid the seeds for the discovery of radioactivity through his interest in and studies of X-rays, which significantly influenced physicist Henri Becquerel. Radioactivity was discovered in 1896 by Becquerel while working with phosphorescent materials. These materials glow in the dark after exposure to light, and Becquerel suspected that the glow produced in cathode-ray tubes by X-rays might be associated with phosphorescence. He wrapped a photographic plate in black paper and placed various phosphorescent salts on it. All results were negative until he used uranium salts. The uranium salts caused a blackening of the plate in spite of the plate being wrapped in black paper. In 1897, Marie Curie began studying the radiation emitted by uranium compounds. Curie named the radiation rayons de Becquerel, "Becquerel Rays" and showed that these rays were a property of atoms. While X-rays were produced using electrical energy, the source of energy for radiation was a mystery.', 'Wikipedia: Radioactive decay', 'https://en.wikipedia.org/w/index.php?title=Radioactive_decay&oldid=1381429181', 'CC BY-SA 4.0. Wikipedia contributors (see page history). Excerpted and split into passages.'
where not exists (select 1 from public.content_chunks where topic_id = 'atoms-nuclear' and body = 'Henri Poincaré laid the seeds for the discovery of radioactivity through his interest in and studies of X-rays, which significantly influenced physicist Henri Becquerel. Radioactivity was discovered in 1896 by Becquerel while working with phosphorescent materials. These materials glow in the dark after exposure to light, and Becquerel suspected that the glow produced in cathode-ray tubes by X-rays might be associated with phosphorescence. He wrapped a photographic plate in black paper and placed various phosphorescent salts on it. All results were negative until he used uranium salts. The uranium salts caused a blackening of the plate in spite of the plate being wrapped in black paper. In 1897, Marie Curie began studying the radiation emitted by uranium compounds. Curie named the radiation rayons de Becquerel, "Becquerel Rays" and showed that these rays were a property of atoms. While X-rays were produced using electrical energy, the source of energy for radiation was a mystery.');
insert into public.content_chunks (topic_id, title, body, source_name, source_url, license)
select 'atoms-nuclear', 'Radioactive decay: History of discovery', 'In 1899, Julius Elster and Hans Geitel performed key experiments to find the energy source for radioactivity, excluding extraction of energy from air by measurements in a vacuum and extraction of energy from outer space by measurements 300m down a mine in the Harz mountains. If the atoms themselves were the source of energy, this meant the seemingly immutable atoms must be altered when emitting the rays. In 1900 Curie summarized the puzzle of radioactivity as a choice between two equally unlikely possibilities: either energy was not conserved or chemical elements could be transmuted. Rutherford was the first to realize that all such elements decay in accordance with the same mathematical exponential formula. Rutherford and his student Frederick Soddy were the first to realize that many decay processes resulted in the transmutation of one element to another. Subsequently, the radioactive displacement law of Fajans and Soddy was formulated to describe the products of alpha and beta decay. The early researchers also discovered that many other chemical elements, besides uranium, have radioactive isotopes. A systematic search for the total radioactivity in uranium ores also guided Pierre and Marie Curie to isolate two new elements: polonium and radium. Except for the radioactivity of radium, the chemical similarity of radium to barium made these two elements difficult to distinguish.', 'Wikipedia: Radioactive decay', 'https://en.wikipedia.org/w/index.php?title=Radioactive_decay&oldid=1381429181', 'CC BY-SA 4.0. Wikipedia contributors (see page history). Excerpted and split into passages.'
where not exists (select 1 from public.content_chunks where topic_id = 'atoms-nuclear' and body = 'In 1899, Julius Elster and Hans Geitel performed key experiments to find the energy source for radioactivity, excluding extraction of energy from air by measurements in a vacuum and extraction of energy from outer space by measurements 300m down a mine in the Harz mountains. If the atoms themselves were the source of energy, this meant the seemingly immutable atoms must be altered when emitting the rays. In 1900 Curie summarized the puzzle of radioactivity as a choice between two equally unlikely possibilities: either energy was not conserved or chemical elements could be transmuted. Rutherford was the first to realize that all such elements decay in accordance with the same mathematical exponential formula. Rutherford and his student Frederick Soddy were the first to realize that many decay processes resulted in the transmutation of one element to another. Subsequently, the radioactive displacement law of Fajans and Soddy was formulated to describe the products of alpha and beta decay. The early researchers also discovered that many other chemical elements, besides uranium, have radioactive isotopes. A systematic search for the total radioactivity in uranium ores also guided Pierre and Marie Curie to isolate two new elements: polonium and radium. Except for the radioactivity of radium, the chemical similarity of radium to barium made these two elements difficult to distinguish.');
insert into public.content_chunks (topic_id, title, body, source_name, source_url, license)
select 'atoms-nuclear', 'Radioactive decay: History of discovery', 'Marie and Pierre Curie also coined the term "radioactivity" to define the emission of ionizing radiation by some heavy elements. (Later the term was generalized to all elements.) Their research on the penetrating rays in uranium and the discovery of radium launched an era of using radium for the treatment of cancer. Their exploration of radium could be seen as the first peaceful use of nuclear energy and the start of modern nuclear medicine.', 'Wikipedia: Radioactive decay', 'https://en.wikipedia.org/w/index.php?title=Radioactive_decay&oldid=1381429181', 'CC BY-SA 4.0. Wikipedia contributors (see page history). Excerpted and split into passages.'
where not exists (select 1 from public.content_chunks where topic_id = 'atoms-nuclear' and body = 'Marie and Pierre Curie also coined the term "radioactivity" to define the emission of ionizing radiation by some heavy elements. (Later the term was generalized to all elements.) Their research on the penetrating rays in uranium and the discovery of radium launched an era of using radium for the treatment of cancer. Their exploration of radium could be seen as the first peaceful use of nuclear energy and the start of modern nuclear medicine.');
insert into public.content_chunks (topic_id, title, body, source_name, source_url, license)
select 'atoms-nuclear', 'Radioactive decay: Early health dangers', 'The dangers of ionizing radiation due to radioactivity and X-rays were not immediately recognized.', 'Wikipedia: Radioactive decay', 'https://en.wikipedia.org/w/index.php?title=Radioactive_decay&oldid=1381429181', 'CC BY-SA 4.0. Wikipedia contributors (see page history). Excerpted and split into passages.'
where not exists (select 1 from public.content_chunks where topic_id = 'atoms-nuclear' and body = 'The dangers of ionizing radiation due to radioactivity and X-rays were not immediately recognized.');
insert into public.content_chunks (topic_id, title, body, source_name, source_url, license)
select 'atoms-nuclear', 'Radioactive decay: X-rays', 'The discovery of X‑rays by Wilhelm Röntgen in 1895 led to widespread experimentation by scientists, physicians, and inventors. Many people began recounting stories of burns, hair loss and worse in technical journals as early as 1896. In February of that year, Professor Daniel and Dr. Dudley of Vanderbilt University performed an experiment involving X-raying Dudley''s head that resulted in his hair loss. A report by Dr. H.D. Hawks, of his suffering severe hand and chest burns in an X-ray demonstration, was the first of many other reports in Electrical Review. Other experimenters, including Elihu Thomson and Nikola Tesla, also reported burns. Thomson deliberately exposed a finger to an X-ray tube over a period of time and suffered pain, swelling, and blistering. Other effects, including ultraviolet rays and ozone, were sometimes blamed for the damage, and many physicians still claimed that there were no effects from X-ray exposure at all.', 'Wikipedia: Radioactive decay', 'https://en.wikipedia.org/w/index.php?title=Radioactive_decay&oldid=1381429181', 'CC BY-SA 4.0. Wikipedia contributors (see page history). Excerpted and split into passages.'
where not exists (select 1 from public.content_chunks where topic_id = 'atoms-nuclear' and body = 'The discovery of X‑rays by Wilhelm Röntgen in 1895 led to widespread experimentation by scientists, physicians, and inventors. Many people began recounting stories of burns, hair loss and worse in technical journals as early as 1896. In February of that year, Professor Daniel and Dr. Dudley of Vanderbilt University performed an experiment involving X-raying Dudley''s head that resulted in his hair loss. A report by Dr. H.D. Hawks, of his suffering severe hand and chest burns in an X-ray demonstration, was the first of many other reports in Electrical Review. Other experimenters, including Elihu Thomson and Nikola Tesla, also reported burns. Thomson deliberately exposed a finger to an X-ray tube over a period of time and suffered pain, swelling, and blistering. Other effects, including ultraviolet rays and ozone, were sometimes blamed for the damage, and many physicians still claimed that there were no effects from X-ray exposure at all.');
insert into public.content_chunks (topic_id, title, body, source_name, source_url, license)
select 'atoms-nuclear', 'Radioactive decay: X-rays', 'Despite this, there were some early systematic hazard investigations, and as early as 1902 William Herbert Rollins wrote almost despairingly that his warnings about the dangers involved in the careless use of X-rays were not being heeded, neither by industry nor by his colleagues. By this time, Rollins had proved that X-rays could kill experimental animals, could cause a pregnant guinea pig to abort, and that they could kill a foetus. He also stressed that "animals vary in susceptibility to the external action of X-light" and warned that these differences be considered when patients were treated by means of X-rays.', 'Wikipedia: Radioactive decay', 'https://en.wikipedia.org/w/index.php?title=Radioactive_decay&oldid=1381429181', 'CC BY-SA 4.0. Wikipedia contributors (see page history). Excerpted and split into passages.'
where not exists (select 1 from public.content_chunks where topic_id = 'atoms-nuclear' and body = 'Despite this, there were some early systematic hazard investigations, and as early as 1902 William Herbert Rollins wrote almost despairingly that his warnings about the dangers involved in the careless use of X-rays were not being heeded, neither by industry nor by his colleagues. By this time, Rollins had proved that X-rays could kill experimental animals, could cause a pregnant guinea pig to abort, and that they could kill a foetus. He also stressed that "animals vary in susceptibility to the external action of X-light" and warned that these differences be considered when patients were treated by means of X-rays.');
insert into public.content_chunks (topic_id, title, body, source_name, source_url, license)
select 'atoms-nuclear', 'Half-life', 'Half-life (symbol t½) is the time required for a quantity (of substance) to reduce to half of its initial value. The term is commonly used in nuclear physics to describe how quickly unstable atoms undergo radioactive decay or how long stable atoms survive. The term is also used more generally to characterize any type of exponential (or, rarely, non-exponential) decay. For example, the medical sciences refer to the biological half-life of drugs and other chemicals in the human body. The converse of half-life is doubling time, an exponential property which increases by a factor of 2 rather than reducing by that factor. The original term, half-life period, dating to Ernest Rutherford''s discovery of the principle in 1907, was shortened to half-life in the early 1950s. Rutherford applied the principle of a radioactive element''s half-life in studies of age determination of rocks by measuring the decay period of radium to lead-206. Half-life is constant over the lifetime of an exponentially decaying quantity, and it is a characteristic unit for the exponential decay equation. The accompanying table shows the reduction of a quantity as a function of the number of half-lives elapsed.', 'Wikipedia: Half-life', 'https://en.wikipedia.org/w/index.php?title=Half-life&oldid=1373221894', 'CC BY-SA 4.0. Wikipedia contributors (see page history). Excerpted and split into passages.'
where not exists (select 1 from public.content_chunks where topic_id = 'atoms-nuclear' and body = 'Half-life (symbol t½) is the time required for a quantity (of substance) to reduce to half of its initial value. The term is commonly used in nuclear physics to describe how quickly unstable atoms undergo radioactive decay or how long stable atoms survive. The term is also used more generally to characterize any type of exponential (or, rarely, non-exponential) decay. For example, the medical sciences refer to the biological half-life of drugs and other chemicals in the human body. The converse of half-life is doubling time, an exponential property which increases by a factor of 2 rather than reducing by that factor. The original term, half-life period, dating to Ernest Rutherford''s discovery of the principle in 1907, was shortened to half-life in the early 1950s. Rutherford applied the principle of a radioactive element''s half-life in studies of age determination of rocks by measuring the decay period of radium to lead-206. Half-life is constant over the lifetime of an exponentially decaying quantity, and it is a characteristic unit for the exponential decay equation. The accompanying table shows the reduction of a quantity as a function of the number of half-lives elapsed.');
insert into public.content_chunks (topic_id, title, body, source_name, source_url, license)
select 'atoms-nuclear', 'Half-life: Probabilistic nature', 'A half-life often describes the decay of discrete entities, such as radioactive atoms. In that case, it does not work to use the definition that states "half-life is the time required for exactly half of the entities to decay". For example, if there is just one radioactive atom, and its half-life is one second, there will not be "half of an atom" left after one second. Instead, the half-life is defined in terms of probability: "Half-life is the time required for exactly half of the entities to decay on average". In other words, the probability of a radioactive atom decaying within its half-life is 50%. For example, the accompanying image is a simulation of many identical atoms undergoing radioactive decay. Note that after one half-life there are not exactly one-half of the atoms remaining, only approximately, because of the random variation in the process. Nevertheless, when there are many identical atoms decaying (right boxes), the law of large numbers suggests that it is a very good approximation to say that half of the atoms remain after one half-life. Various simple exercises can demonstrate probabilistic decay, for example involving flipping coins or running a statistical computer program.', 'Wikipedia: Half-life', 'https://en.wikipedia.org/w/index.php?title=Half-life&oldid=1373221894', 'CC BY-SA 4.0. Wikipedia contributors (see page history). Excerpted and split into passages.'
where not exists (select 1 from public.content_chunks where topic_id = 'atoms-nuclear' and body = 'A half-life often describes the decay of discrete entities, such as radioactive atoms. In that case, it does not work to use the definition that states "half-life is the time required for exactly half of the entities to decay". For example, if there is just one radioactive atom, and its half-life is one second, there will not be "half of an atom" left after one second. Instead, the half-life is defined in terms of probability: "Half-life is the time required for exactly half of the entities to decay on average". In other words, the probability of a radioactive atom decaying within its half-life is 50%. For example, the accompanying image is a simulation of many identical atoms undergoing radioactive decay. Note that after one half-life there are not exactly one-half of the atoms remaining, only approximately, because of the random variation in the process. Nevertheless, when there are many identical atoms decaying (right boxes), the law of large numbers suggests that it is a very good approximation to say that half of the atoms remain after one half-life. Various simple exercises can demonstrate probabilistic decay, for example involving flipping coins or running a statistical computer program.');
insert into public.content_chunks (topic_id, title, body, source_name, source_url, license)
select 'atoms-nuclear', 'Half-life: Formulas for half-life in exponential decay', 'An exponential decay can be described by any of the following four equivalent formulas: N0 is the initial quantity of the substance that will decay (this quantity may be measured in grams, moles, number of atoms, etc.), N(t) is the quantity that still remains and has not yet decayed after a time t, τ is a positive number called the mean lifetime of the decaying quantity, λ is a positive number called the decay constant of the decaying quantity. The three parameters t½, τ, and λ are directly related in the following way:', 'Wikipedia: Half-life', 'https://en.wikipedia.org/w/index.php?title=Half-life&oldid=1373221894', 'CC BY-SA 4.0. Wikipedia contributors (see page history). Excerpted and split into passages.'
where not exists (select 1 from public.content_chunks where topic_id = 'atoms-nuclear' and body = 'An exponential decay can be described by any of the following four equivalent formulas: N0 is the initial quantity of the substance that will decay (this quantity may be measured in grams, moles, number of atoms, etc.), N(t) is the quantity that still remains and has not yet decayed after a time t, τ is a positive number called the mean lifetime of the decaying quantity, λ is a positive number called the decay constant of the decaying quantity. The three parameters t½, τ, and λ are directly related in the following way:');
insert into public.content_chunks (topic_id, title, body, source_name, source_url, license)
select 'atoms-nuclear', 'Half-life: Half-life and reaction orders', 'In chemical kinetics, the value of the half-life depends on the reaction order:', 'Wikipedia: Half-life', 'https://en.wikipedia.org/w/index.php?title=Half-life&oldid=1373221894', 'CC BY-SA 4.0. Wikipedia contributors (see page history). Excerpted and split into passages.'
where not exists (select 1 from public.content_chunks where topic_id = 'atoms-nuclear' and body = 'In chemical kinetics, the value of the half-life depends on the reaction order:');
insert into public.content_chunks (topic_id, title, body, source_name, source_url, license)
select 'atoms-nuclear', 'Half-life: Zero order kinetics', 'The rate of this kind of reaction does not depend on the substrate concentration, [A]. Thus the concentration decreases linearly. In order to find the half-life, we have to replace the concentration value for the initial concentration divided by 2: This t½ formula indicates that the half-life for a zero order reaction depends on the initial concentration and the rate constant.', 'Wikipedia: Half-life', 'https://en.wikipedia.org/w/index.php?title=Half-life&oldid=1373221894', 'CC BY-SA 4.0. Wikipedia contributors (see page history). Excerpted and split into passages.'
where not exists (select 1 from public.content_chunks where topic_id = 'atoms-nuclear' and body = 'The rate of this kind of reaction does not depend on the substrate concentration, [A]. Thus the concentration decreases linearly. In order to find the half-life, we have to replace the concentration value for the initial concentration divided by 2: This t½ formula indicates that the half-life for a zero order reaction depends on the initial concentration and the rate constant.');
insert into public.content_chunks (topic_id, title, body, source_name, source_url, license)
select 'atoms-nuclear', 'Half-life: First order kinetics', 'In first order reactions, the rate of reaction will be proportional to the concentration of the reactant. Thus the concentration will decrease exponentially. as time progresses until it reaches zero, and the half-life will be constant, independent of concentration. The time t½ for [A] to decrease from [A]0 to ⁠1/2⁠[A]0 in a first-order reaction is given by the following equation: For a first-order reaction, the half-life of a reactant is independent of its initial concentration. Therefore, if the concentration of A at some arbitrary stage of the reaction is [A], then it will have fallen to ⁠1/2⁠[A] after a further interval of ⁠ ⁠ Hence, the half-life of a first order reaction is given as the following: The half-life of a first order reaction is independent of its initial concentration and depends solely on the reaction rate constant, k.', 'Wikipedia: Half-life', 'https://en.wikipedia.org/w/index.php?title=Half-life&oldid=1373221894', 'CC BY-SA 4.0. Wikipedia contributors (see page history). Excerpted and split into passages.'
where not exists (select 1 from public.content_chunks where topic_id = 'atoms-nuclear' and body = 'In first order reactions, the rate of reaction will be proportional to the concentration of the reactant. Thus the concentration will decrease exponentially. as time progresses until it reaches zero, and the half-life will be constant, independent of concentration. The time t½ for [A] to decrease from [A]0 to ⁠1/2⁠[A]0 in a first-order reaction is given by the following equation: For a first-order reaction, the half-life of a reactant is independent of its initial concentration. Therefore, if the concentration of A at some arbitrary stage of the reaction is [A], then it will have fallen to ⁠1/2⁠[A] after a further interval of ⁠ ⁠ Hence, the half-life of a first order reaction is given as the following: The half-life of a first order reaction is independent of its initial concentration and depends solely on the reaction rate constant, k.');
insert into public.content_chunks (topic_id, title, body, source_name, source_url, license)
select 'atoms-nuclear', 'Half-life: Second order kinetics', 'In second order reactions, the rate of reaction is proportional to the square of the concentration. By integrating this rate, it can be shown that the concentration [A] of the reactant decreases following this formula: We can set [A] to half the initial concentration [A]0/2 and rename t to t½, then rearrange the above to find the half-life t½ of the reactant: This shows that the half-life of second order reactions depends on the initial concentration and rate constant.', 'Wikipedia: Half-life', 'https://en.wikipedia.org/w/index.php?title=Half-life&oldid=1373221894', 'CC BY-SA 4.0. Wikipedia contributors (see page history). Excerpted and split into passages.'
where not exists (select 1 from public.content_chunks where topic_id = 'atoms-nuclear' and body = 'In second order reactions, the rate of reaction is proportional to the square of the concentration. By integrating this rate, it can be shown that the concentration [A] of the reactant decreases following this formula: We can set [A] to half the initial concentration [A]0/2 and rename t to t½, then rearrange the above to find the half-life t½ of the reactant: This shows that the half-life of second order reactions depends on the initial concentration and rate constant.');
insert into public.content_chunks (topic_id, title, body, source_name, source_url, license)
select 'atoms-nuclear', 'Half-life: Decay by two or more processes', 'Some quantities decay by two exponential-decay processes simultaneously. In this case, the actual half-life T½ can be related to the half-lives t1 and t2 that the quantity would have if each of the decay processes acted in isolation: For a proof of these formulas, see Exponential decay § Decay by two or more processes.', 'Wikipedia: Half-life', 'https://en.wikipedia.org/w/index.php?title=Half-life&oldid=1373221894', 'CC BY-SA 4.0. Wikipedia contributors (see page history). Excerpted and split into passages.'
where not exists (select 1 from public.content_chunks where topic_id = 'atoms-nuclear' and body = 'Some quantities decay by two exponential-decay processes simultaneously. In this case, the actual half-life T½ can be related to the half-lives t1 and t2 that the quantity would have if each of the decay processes acted in isolation: For a proof of these formulas, see Exponential decay § Decay by two or more processes.');
